/**
 * What an install is offered, without a speech model anywhere near it.
 *
 * The track itself is generated by `src/subtitles.ts` against models that need 368 MiB of weights;
 * what a player is *told* is decided here, and it is the part that must not mislead: a track that
 * is not finished must not be offered, and one that is must be offered with the timings of the cut.
 */

import assert from "node:assert/strict";
import { mkdtemp, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { test } from "node:test";

import { handleSubtitles, handleTrack, SubtitleEngine } from "../src/subtitles.js";
import type { Settings } from "../src/env.js";

const settings = (cacheDir: string): Settings =>
  ({
    cacheDir,
    subtitles: true,
    subtitlesLanguage: "en",
    subtitlesTtlHours: 24,
    subtitlesChunkSeconds: 300,
  }) as unknown as Settings;

test("an unfinished track is not offered, and a finished one is", async () => {
  const cacheDir = await mkdtemp(path.join(tmpdir(), "tidb-subs-"));
  const dir = path.join(cacheDir, "subs", "abc123");
  await writeFile(path.join(cacheDir, "placeholder"), "");
  const ready = { track: async () => path.join(dir, "track.vtt"), key: "abc123", cues: 12 };

  const missing = await handleSubtitles(
    {
      settings: settings(cacheDir),
      subtitles: { trackForEpisode: async () => null } as unknown as SubtitleEngine,
      request: new Request("http://localhost/subs/subtitles/series/tt1:1:1.json"),
      encodedConfig: "cfg",
      origin: "https://addon.example",
    },
    "tt1:1:1",
  );
  assert.deepEqual(await missing.json(), { subtitles: [] }, "nothing to choose yet");

  const offered = await handleSubtitles(
    {
      settings: settings(cacheDir),
      subtitles: { trackForEpisode: async () => ready } as unknown as SubtitleEngine,
      request: new Request("http://localhost/subs/subtitles/series/tt1:1:1.json"),
      encodedConfig: "cfg",
      origin: "https://addon.example",
    },
    "tt1:1:1",
  );
  const body = (await offered.json()) as { subtitles: Array<{ url: string; lang: string; id: string }> };
  assert.equal(body.subtitles.length, 1);
  assert.equal(body.subtitles[0]!.lang, "en");
  assert.equal(body.subtitles[0]!.url, "https://addon.example/cfg/vtt?f=abc123");
});

test("the track is served as WebVTT, and cacheable for as long as it is kept", async () => {
  const cacheDir = await mkdtemp(path.join(tmpdir(), "tidb-subs-"));
  const file = path.join(cacheDir, "track.vtt");
  await writeFile(file, "WEBVTT\n\n00:00:10.000 --> 00:00:12.000\nHello\n");

  const response = await handleTrack({
    settings: settings(cacheDir),
    subtitles: { track: async () => file } as unknown as SubtitleEngine,
    request: new Request("http://localhost/cfg/vtt?f=abc123"),
    encodedConfig: "cfg",
  });
  assert.equal(response.status, 200);
  assert.match(response.headers.get("content-type") ?? "", /text\/vtt/);
  // A finished track never changes and is tiny, so a player may keep it for the day the
  // deployment keeps it: the two lifetimes are the same number on purpose.
  assert.equal(response.headers.get("cache-control"), "public, max-age=86400");
  assert.match(await response.text(), /Hello/);

  const gone = await handleTrack({
    settings: settings(cacheDir),
    subtitles: { track: async () => null } as unknown as SubtitleEngine,
    request: new Request("http://localhost/cfg/vtt?f=missing"),
    encodedConfig: "cfg",
  });
  assert.equal(gone.status, 404, "a repeated expiry is a 404, not a broken file");
});

test("a track's clock is the cut video's, and nothing is planned without the source's length", async () => {
  const engine = new SubtitleEngine(
    settings(await mkdtemp(path.join(tmpdir(), "tidb-subs-"))),
    { available: async () => false, lastError: "not installed" } as never,
  );
  const windows = [{ type: "intro" as const, startMs: 228_665, endMs: 246_498 }];

  // Nothing to time against: the last window would be open-ended, so every offset after it would
  // be a guess -- exactly the misaligned track this exists to avoid.
  assert.equal(engine.ensure("key1", "http://source/file.mkv", { durationMs: null, windows, cardMs: 10_000 }, true), null);
  // Not asked for: no job, no download, no CPU.
  assert.equal(engine.ensure("key2", "http://source/file.mkv", { durationMs: 3_600_000, windows, cardMs: 10_000 }, false), null);

  const job = engine.ensure("key3", "http://source/file.mkv", { durationMs: 3_600_000, windows, cardMs: 10_000 }, true);
  assert.ok(job, "a planned job");
  assert.ok(job!.chunks > 5, `${job!.chunks} chunks of five minutes`);
  assert.equal(job!.ready, false);
  assert.equal(await engine.track("key3"), null, "and nothing is offered until it is finished");
});
